-- Total revenue generated by the company
SELECT
    SUM(sales_amount)
FROM Alata_dw.fact_sales;

-- Revenue generated by country
SELECT
    dc.country,
    SUM(fs.sales_amount) revenue
FROM Alata_dw.fact_sales fs
JOIN Alata_dw.dim_customer dc
    ON fs.customer_id = dc.customer_id
GROUP BY dc.country
ORDER BY revenue DESC;

-- Top 10 products by revenue
SELECT
    dp.product_name,
    SUM(fs.sales_amount) revenue
FROM Alata_dw.fact_sales fs
JOIN Alata_dw.dim_product dp
    ON fs.product_id = dp.product_id
GROUP BY dp.product_name
ORDER BY revenue DESC
LIMIT 10;

-- monthly revenue trend
SELECT
    dd.year,
    dd.month,
    SUM(fs.sales_amount)
FROM Alata_dw.fact_sales fs
JOIN Alata_dw.dim_date dd
    ON fs.date_key = dd.date_key
GROUP BY
    dd.year,
    dd.month
ORDER BY
    dd.year,
    dd.month;